import { createRouter } from './router.js';

export const router = createRouter();
router.add('GET', '/users/:id', ({ params }) => 'user ' + params.id);
router.add('GET', '/search', ({ query }) => 'search for ' + (query.q ?? ''));
router.add('GET', '/files/*', ({ params }) => 'file ' + params.rest);

export function handle(method, url) {
  const m = router.match(method, url);
  if (!m) return '404';
  return m.handler({ params: m.params, query: m.query });
}

