import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createRouter } from '../router.js';
import { handle } from '../app.js';
test('existing behaviour', () => {
  const r = createRouter();
  r.add('GET', '/a/:x/b', 'h');
  assert.deepEqual(r.match('GET', '/a/1/b'), { handler: 'h', params: { x: '1' }, query: {} });
  assert.equal(r.match('POST', '/a/1/b'), null);
  assert.equal(r.match('GET', '/a/1'), null);
});
test('query strings', () => {
  const r = createRouter();
  r.add('GET', '/s', 'h');
  assert.deepEqual(r.match('GET', '/s?q=cat&page=2'), { handler: 'h', params: {}, query: { q: 'cat', page: '2' } });
  assert.deepEqual(r.match('GET', '/s?q=a+b%21'), { handler: 'h', params: {}, query: { q: 'a b!' } });
  assert.deepEqual(r.match('GET', '/s?').query, {});
});
test('wildcards', () => {
  const r = createRouter();
  r.add('GET', '/files/*', 'h');
  assert.deepEqual(r.match('GET', '/files/a/b/c.txt').params, { rest: 'a/b/c.txt' });
  assert.deepEqual(r.match('GET', '/files/x').params, { rest: 'x' });
  assert.equal(r.match('GET', '/files'), null);
  assert.equal(r.match('GET', '/files/'), null);
});
test('trailing slash', () => {
  const r = createRouter();
  r.add('GET', '/users/:id', 'h');
  assert.deepEqual(r.match('GET', '/users/7/').params, { id: '7' });
  assert.deepEqual(r.match('GET', '/users/7/?x=1').query, { x: '1' });
});
test('app', () => {
  assert.equal(handle('GET', '/users/42'), 'user 42');
  assert.equal(handle('GET', '/search?q=dogs'), 'search for dogs');
  assert.equal(handle('GET', '/files/docs/readme.md'), 'file docs/readme.md');
  assert.equal(handle('GET', '/nothing'), '404');
});

