// A tiny router: add(method, pattern, handler) and match(method, path)
export function createRouter() {
  const routes = [];
  return {
    add(method, pattern, handler) {
      routes.push({ method, parts: pattern.split('/').filter(Boolean), handler });
    },
    match(method, url) {
      const q = url.indexOf('?');
      const path = q === -1 ? url : url.slice(0, q);
      const query = q === -1 ? {} : Object.fromEntries(new URLSearchParams(url.slice(q + 1)));
      const parts = path.split('/').filter(Boolean);
      for (const r of routes) {
        if (r.method !== method) continue;
        const wild = r.parts[r.parts.length - 1] === '*';
        if (wild ? parts.length < r.parts.length : r.parts.length !== parts.length) continue;
        const params = {};
        let ok = true;
        for (let i = 0; i < r.parts.length; i++) {
          if (r.parts[i] === '*' && i === r.parts.length - 1) params.rest = parts.slice(i).join('/');
          else if (r.parts[i].startsWith(':')) params[r.parts[i].slice(1)] = parts[i];
          else if (r.parts[i] !== parts[i]) { ok = false; break; }
        }
        if (ok) return { handler: r.handler, params, query };
      }
      return null;
    },
  };
}
